.php?action=edit&post=450844&wpb-backend-editor']]],'Maximum number of bundles returned per page.'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Please enter an integer higher than or equal to %s.'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Please enter an integer lower than or equal to %s.'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Please enter an integer that is a multiple of %s.'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Virtual bundles are intangible and are not shipped. When this option is enabled, any physical products added to this bundle will be treated as virtual.'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Bundled Products'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Enable this option to track stock for this SKU only. This option does not affect the inventory management of bundled products. <a class="bundles-inventory-learn-more-link" href="%1$s" target="_blank" rel="noreferrer">Learn more</a>'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'No'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Yes'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Matching configurations'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Allow only one of this bundle to be bought in a single order. Choose the <strong>Matching configurations</strong> option to prevent customers from purchasing <strong>identically configured</strong> bundles in the same order.'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Unassembled'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Bundled products preserve their individual dimensions, weight and shipping classes. A virtual container item keeps them grouped together in the cart.'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Assembled'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Bundled products are assembled and shipped in a new physical container with the specified dimensions, weight and shipping class. The entire bundle appears as a single physical item.<br><br>To ship a bundled product outside this container, navigate to the <strong>Bundled Products</strong> tab, expand its settings and enable <strong>Shipped Individually</strong>. Bundled products that are <strong>Shipped Individually</strong> preserve their own dimensions, weight and shipping classes.'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Bundle type'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'<a href="%s" target="_blank">Unassembled</a> bundles do not have any shipping options to configure. The contents of this bundle preserve their dimensions, weight and shipping classes.'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Assembled weight'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Controls whether to ignore or preserve the weight of assembled bundled items.<br><br> <strong>Ignore</strong> &ndash; The specified Weight is the total weight of the entire bundle.<br><br> <strong>Preserve</strong> &ndash; The specified Weight is treated as a container weight. The total weight of the bundle is the sum of: i) the container weight, and ii) the weight of all assembled bundled items.'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Ignore'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Preserve'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Bundle-sells'=>['saveStringInDb'=>true,'cmp'=>['wpml-string-translation',1],'names'=>[],'urls'=>[['kind'=>9,'url'=>'/wp-admin/post.php?action=edit&post=450844&wpb-backend-editor']]],'Supports Simple products only.'=>['saveStringInDb'